const query = $json.query;
const invalid = () => [{ json: { reviewResult: 'invalid', statusCode: 400 } }];

if (!query || typeof query !== 'object' || Array.isArray(query)) {
  return invalid();
}

const allowedFields = new Set(['lead_id', 'token', 'decision']);
if (Object.keys(query).some((field) => !allowedFields.has(field))) {
  return invalid();
}

const leadIdText = typeof query.lead_id === 'string' ? query.lead_id.trim() : '';
const token = typeof query.token === 'string' ? query.token.trim().toLowerCase() : '';
const decision = typeof query.decision === 'string' ? query.decision.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

if (!/^[1-9]\d*$/.test(leadIdText) || !uuidPattern.test(token) || !['approve', 'reject'].includes(decision)) {
  return invalid();
}

const leadId = Number(leadIdText);
if (!Number.isSafeInteger(leadId)) {
  return invalid();
}

return [{ json: { reviewResult: 'validated', leadId, token, decision } }];

const data = $json;
const actionLabel = data.decision === 'approve' ? 'Approve draft' : 'Reject draft';
const actionDescription = data.decision === 'approve'
  ? 'Approve this saved response draft and send it to the lead.'
  : 'Reject this saved response draft. No email will be sent.';
const reviewHtml = `<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>FlowPilot confirmation</title><style>body{font-family:system-ui,sans-serif;max-width:36rem;margin:4rem auto;padding:0 1.25rem;color:#172033}main{border:1px solid #d8dee9;border-radius:12px;padding:2rem;box-shadow:0 8px 28px rgba(23,32,51,.08)}h1{font-size:1.5rem;margin-top:0}p{line-height:1.5}button{border:0;border-radius:8px;padding:.8rem 1.1rem;font:inherit;font-weight:650;color:#fff;background:#2457d6;cursor:pointer}</style></head><body><main><h1>Confirm ${actionLabel.toLowerCase()}</h1><p>${actionDescription}</p><p>No change has been made yet. Continue only if you intended this decision.</p><form method='post' action='?' autocomplete='off'><input type='hidden' name='lead_id' value='${data.leadId}'><input type='hidden' name='token' value='${data.token}'><input type='hidden' name='decision' value='${data.decision}'><button type='submit'>${actionLabel}</button></form></main></body></html>`;
return [{ json: { reviewHtml } }];

const body = $json.body;
const query = $json.query;
const invalid = () => [{ json: { approvalResult: 'invalid', statusCode: 400 } }];

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return invalid();
}
if (query && (typeof query !== 'object' || Array.isArray(query) || Object.keys(query).length > 0)) {
  return invalid();
}

const allowedFields = new Set(['lead_id', 'token', 'decision']);
if (Object.keys(body).some((field) => !allowedFields.has(field))) {
  return invalid();
}

const leadIdText = typeof body.lead_id === 'string' ? body.lead_id.trim() : '';
const token = typeof body.token === 'string' ? body.token.trim().toLowerCase() : '';
const decision = typeof body.decision === 'string' ? body.decision.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

if (!/^[1-9]\d*$/.test(leadIdText) || !uuidPattern.test(token) || !['approve', 'reject'].includes(decision)) {
  return invalid();
}

const leadId = Number(leadIdText);
if (!Number.isSafeInteger(leadId)) {
  return invalid();
}

return [{ json: { approvalResult: 'validated', leadId, token, decision } }];

const row = $json;
const request = $('Validate Approval Request').item.json;

if (row.error) {
  return [{ json: { approvalResult: 'error', statusCode: 503, error: { code: 'APPROVAL_ERROR', message: 'The approval request could not be processed.' } } }];
}

const authorized = row.authorized === true || row.authorized === 'true';
if (!authorized || !row.id || !['approved', 'rejected'].includes(row.draft_status)) {
  return [{ json: { approvalResult: 'invalid', statusCode: 400 } }];
}

if ((request.decision === 'approve' && row.draft_status !== 'approved') || (request.decision === 'reject' && row.draft_status !== 'rejected')) {
  return [{ json: { approvalResult: 'error', statusCode: 503, error: { code: 'APPROVAL_ERROR', message: 'The approval request could not be processed.' } } }];
}

if (row.draft_status === 'rejected') {
  return [{ json: { approvalResult: 'rejected', statusCode: 200 } }];
}

return [{
  json: {
    approvalResult: 'approved',
    statusCode: 200,
    leadId: Number(row.id),
    persisted: {
      recipient: row.email,
      subject: row.draft_subject,
      body: row.draft_body,
    },
  },
}];

const data = $json;
const sender = String($env.FLOWPILOT_LEAD_EMAIL_FROM ?? '').trim();
const addressPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const recipient = typeof data.persisted?.recipient === 'string' ? data.persisted.recipient.trim() : '';
const subject = typeof data.persisted?.subject === 'string' ? data.persisted.subject : '';
const body = typeof data.persisted?.body === 'string' ? data.persisted.body : '';

if (!addressPattern.test(sender) || !addressPattern.test(recipient) || !subject.trim() || !body.trim() || /[\r\n]/.test(subject)) {
  return [{ json: { approvalResult: 'email_error', statusCode: 503, error: { code: 'EMAIL_ERROR', message: 'The draft was approved, but the response email could not be sent.' } } }];
}

return [{
  json: {
    approvalResult: 'email_ready',
    leadId: data.leadId,
    email: { sender, recipient, subject, body },
  },
}];

const result = $json;
const prepared = $('Prepare Approved Email').item.json;

if (result.error || result.success === false) {
  return [{ json: { approvalResult: 'email_error', statusCode: 503, error: { code: 'EMAIL_ERROR', message: 'The draft was approved, but the response email could not be sent.' } } }];
}

return [{ json: { approvalResult: 'email_sent', leadId: prepared.leadId } }];

const row = $json;
const recorded = row.recorded === true || row.recorded === 'true';

if (row.error || !recorded || !row.initial_response_sent_at) {
  return [{ json: { approvalResult: 'error', statusCode: 503, error: { code: 'APPROVAL_ERROR', message: 'The approval request could not be completed.' } } }];
}

return [{ json: { approvalResult: 'complete', statusCode: 200 } }];
